package tguser

import (
	"context"
	"fmt"
	"sync/atomic"
	"testing"
	"time"

	"github.com/gotd/td/bin"
	"github.com/gotd/td/telegram"
	"github.com/gotd/td/telegram/uploader"
	"github.com/gotd/td/tg"
)

// Synthetic RPC latency only: no Telegram credentials or network are used.
// Measure the same generated bytes before/after to expose time spent waiting
// for small sequential acknowledgements independently of the network rate cap.
func TestTelegramUploadLatencyFixture(t *testing.T) {
	const size = 12 << 20
	for _, optimized := range []bool{false, true} {
		t.Run(fmt.Sprint(optimized), func(t *testing.T) {
			var calls, active, peak atomic.Int32
			var received atomic.Int64
			api := tg.NewClient(telegram.InvokeFunc(func(ctx context.Context, in bin.Encoder, out bin.Decoder) error {
				req, ok := in.(*tg.UploadSaveBigFilePartRequest)
				if !ok {
					return fmt.Errorf("unexpected RPC %T", in)
				}
				calls.Add(1)
				concurrent := active.Add(1)
				defer active.Add(-1)
				for old := peak.Load(); concurrent > old; old = peak.Load() {
					if peak.CompareAndSwap(old, concurrent) {
						break
					}
				}
				timer := time.NewTimer(5 * time.Millisecond)
				defer timer.Stop()
				select {
				case <-ctx.Done():
					return ctx.Err()
				case <-timer.C:
				}
				received.Add(int64(len(req.Bytes)))
				out.(*tg.BoolBox).Bool = &tg.BoolTrue{}
				return nil
			}))
			u := uploader.NewUploader(api)
			wantCalls, wantPeak := int32(96), int32(1)
			if optimized {
				u.WithPartSize(telegramUploadPartSize).WithThreads(telegramUploadThreads)
				wantCalls, wantPeak = 24, 4
			}
			started := time.Now()
			_, err := u.Upload(context.Background(), uploader.NewUpload("fixture.bin", &generatedVideoReader{remaining: size}, size))
			t.Logf("synthetic 5ms RPC latency; optimized=%v bytes=%d requests=%d peak=%d elapsed=%s", optimized, received.Load(), calls.Load(), peak.Load(), time.Since(started))
			// The latency fixture measures naturally scheduled overlap; race
			// instrumentation may slow source generation enough to reduce it.
			// The barrier-based stream test separately proves all four slots.
			if err != nil || received.Load() != size || calls.Load() != wantCalls || peak.Load() < 1 || peak.Load() > wantPeak || active.Load() != 0 {
				t.Fatal("unexpected transfer", err, received.Load(), calls.Load(), peak.Load(), active.Load())
			}
		})
	}
}
